	@SuppressWarnings("unchecked")
	private static com.sun.tools.javac.util.List<JCAnnotation> getAnnotatedTypeAnnotations(JCTree tree) {
		initAnnotatedType(tree.getClass());
		try {
			return (com.sun.tools.javac.util.List<JCAnnotation>) annotatedTypeAnnotations.get(tree);
		} catch (Exception e) {
			return com.sun.tools.javac.util.List.nil();
		}
