	private static JCExpression getAnnotatedUnderlyingType(JCTree tree) {
		initAnnotatedType(tree.getClass());
		try {
			return (JCExpression) annotatedTypeUnderlying.get(tree);
		} catch (Exception e) {
			return null;
		}
